package com.trampolim.api.education;

import java.util.*;
import java.time.*;
import com.trampolim.api.radar.*;
import static com.trampolim.api.radar.RadarModel.*;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@Service
@ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class AdaptiveService {
 private final JdbcTemplate jdbc;private final LearningAccess access;private final RadarBridge bridge;
 public AdaptiveService(@Qualifier("capacitaJdbcTemplate")JdbcTemplate jdbc,LearningAccess access,RadarBridge bridge){this.jdbc=jdbc;this.access=access;this.bridge=bridge;}
 public record Target(String skillCode,int level){}
 public record Goal(String title,String source,Long sourceId,List<Target> skills,int revision){}
 public record ModulePolicy(List<Long> prerequisites,boolean skipMastered,Integer validityDays,int revision){}
 public List<Map<String,Object>> goals(String email){return jdbc.queryForList("SELECT id,title,source,source_id,source_title,revision,created_at FROM learning_adaptive_goals WHERE student_id=? ORDER BY created_at DESC LIMIT 20",access.account(email).id());}
 private Map<String,Object> own(long uid,UUID id){return jdbc.queryForList("SELECT * FROM learning_adaptive_goals WHERE id=? AND student_id=?",id,uid).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Trilha não encontrada nesta conta."));}
 private List<Target> targets(Object data){var list=new ArrayList<Target>();for(var x:bridge.read(data))list.add(new Target(x.path("skillCode").asText(),x.path("level").asInt()));return list;}
 private void validateTargets(List<Target> values){if(values==null||values.isEmpty()||values.size()>20||values.stream().anyMatch(t->t==null||t.skillCode()==null||!t.skillCode().matches("[a-z][a-z0-9-]{1,63}")||t.level()<1||t.level()>4)||values.stream().map(Target::skillCode).distinct().count()!=values.size())bad("Escolha de uma a vinte competências diferentes, com nível de 1 a 4.");}
 private Map<String,Object> market(String source,long id){var data=bridge.get(source.equals("COMPANY")?"/public/companies/radar-jobs/"+id:"/public/companies/future-demands/"+id);var values=new ArrayList<Target>();for(var x:data.path("requirements").path("skills"))values.add(new Target(x.path("skillCode").asText(),x.path("level").asInt()));validateTargets(values);return Map.of("skills",values,"title",text(data.path(source.equals("COMPANY")?"title":"occupation").asText(),180));}
 @Transactional("capacitaTransactionManager") public Map<String,Object> save(String email,UUID id,Goal input){long uid=access.account(email).id();if(input==null||text(input.title(),180).isEmpty()||!Set.of("MANUAL","COMPANY","FUTURE").contains(Objects.toString(input.source(),"")))bad("Informe o objetivo profissional e a fonte dos requisitos.");List<Target> values=input.skills();String title="";
  if(!input.source().equals("MANUAL")){if(input.sourceId()==null||input.sourceId()<1)bad("Selecione uma vaga ou previsão pública disponível.");var market=market(input.source(),input.sourceId());values=(List<Target>)market.get("skills");title=market.get("title").toString();}else if(input.sourceId()!=null)bad("Objetivo manual não possui referência empresarial.");
  validateTargets(values);bridge.validateSkills(values.stream().map(Target::skillCode).toList());jdbc.queryForObject("SELECT id FROM student_users WHERE id=? FOR UPDATE",Long.class,uid);
  if(id==null){if(jdbc.queryForObject("SELECT count(*) FROM learning_adaptive_goals WHERE student_id=?",Integer.class,uid)>=20)bad("Limite de vinte trilhas. Remova uma trilha antiga para criar outra.");id=UUID.randomUUID();jdbc.update("INSERT INTO learning_adaptive_goals(id,student_id,title,source,source_id,requirements,source_title,source_checked_at) VALUES (?,?,?,?,?,?::jsonb,?,CURRENT_TIMESTAMP)",id,uid,input.title().trim(),input.source(),input.sourceId(),bridge.encode(values),title);}else if(jdbc.update("UPDATE learning_adaptive_goals SET title=?,source=?,source_id=?,requirements=?::jsonb,source_title=?,source_checked_at=CURRENT_TIMESTAMP,revision=revision+1,cached_result=NULL,cached_fingerprint=NULL WHERE id=? AND student_id=? AND revision=?",input.title().trim(),input.source(),input.sourceId(),bridge.encode(values),title,id,uid,input.revision())==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Trilha não encontrada ou versão alterada.");
  audit(uid,id,"ADAPTIVE_GOAL_SAVED");return Map.of("id",id);
 }
 public void delete(String email,UUID id){long uid=access.account(email).id();if(jdbc.update("DELETE FROM learning_adaptive_goals WHERE id=? AND student_id=?",id,uid)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);audit(uid,id,"ADAPTIVE_GOAL_REMOVED");}
 public Map<String,Integer> verified(long uid){var levels=new HashMap<String,Integer>();for(var r:jdbc.queryForList("SELECT a.skill_code,max(a.skill_level) AS level FROM learning_competency_awards a JOIN learning_assessment_attempts t ON t.id=a.attempt_id AND t.student_id=a.student_id AND t.assessment_id=a.assessment_id WHERE a.student_id=? AND a.skill_code IS NOT NULL AND a.revoked_at IS NULL AND (a.valid_until IS NULL OR a.valid_until>CURRENT_TIMESTAMP) AND t.status='SUBMITTED' AND t.passed=TRUE AND t.score_percent=a.score_percent GROUP BY a.skill_code",uid))levels.put(r.get("skill_code").toString(),((Number)r.get("level")).intValue());return levels;}
 private List<Map<String,Object>> units(List<Target> needs){if(needs.isEmpty())return List.of();var args=new ArrayList<Object>();var predicates=new ArrayList<String>();for(var t:needs){predicates.add("v.definition->'competencies' @> ?::jsonb");args.add(bridge.encode(List.of(Map.of("skillCode",t.skillCode()))));}
  return jdbc.queryForList("SELECT a.id,a.title,a.current_version_id,a.course_id,a.module_id,v.definition,m.title AS module_title,m.adaptive_skip_mastered,m.adaptive_revision,c.title AS course_title FROM learning_assessments a JOIN learning_assessment_versions v ON v.id=a.current_version_id JOIN learning_modules m ON m.id=a.module_id JOIN learning_courses c ON c.id=a.course_id JOIN student_users u ON u.id=c.teacher_id WHERE a.status='PUBLISHED' AND c.status='PUBLISHED' AND c.moderation_blocked=FALSE AND u.account_status='ACTIVE' AND ("+String.join(" OR ",predicates)+") ORDER BY m.sort_order,a.id LIMIT 81",args.toArray());
 }
 private String placeholders(Collection<?> ids){return String.join(",",Collections.nCopies(ids.size(),"?"));}
 private Map<Long,List<Map<String,Object>>> lessonData(long uid,Set<Long> ids){var result=new HashMap<Long,List<Map<String,Object>>>();if(ids.isEmpty())return result;var args=new ArrayList<Object>();args.add(uid);args.addAll(ids);
  var rows=jdbc.queryForList("SELECT l.module_id,count(*) AS total,count(p.completed_at) AS completed FROM learning_lessons l LEFT JOIN learning_lesson_progress p ON p.lesson_id=l.id AND p.student_id=? WHERE l.status='PUBLISHED' AND l.validation_status='READY' AND l.module_id IN ("+placeholders(ids)+") GROUP BY l.module_id",args.toArray());for(var row:rows)result.put(((Number)row.get("module_id")).longValue(),new ArrayList<>(List.of(row)));return result;
 }
 private Map<Long,Boolean> completeModules(long uid,Set<Long> ids){var result=new HashMap<Long,Boolean>();if(ids.isEmpty())return result;var lessons=lessonData(uid,ids);var args=new ArrayList<Object>();args.add(uid);args.addAll(ids);var tests=jdbc.queryForList("SELECT a.module_id,(v.definition->>'requiredForCompletion')::boolean AS required,EXISTS(SELECT 1 FROM learning_assessment_attempts t WHERE t.student_id=? AND t.assessment_id=a.id AND t.passed=TRUE) AS passed FROM learning_assessments a JOIN learning_assessment_versions v ON v.id=a.current_version_id WHERE a.status='PUBLISHED' AND a.module_id IN ("+placeholders(ids)+")",args.toArray());
  for(long id:ids){var ls=lessons.get(id);var ts=tests.stream().filter(r->((Number)r.get("module_id")).longValue()==id).toList();boolean done=ls!=null?((Number)ls.get(0).get("total")).longValue()==((Number)ls.get(0).get("completed")).longValue()&&!ts.stream().anyMatch(r->Boolean.TRUE.equals(r.get("required"))&&!Boolean.TRUE.equals(r.get("passed"))):!ts.isEmpty()&&ts.stream().allMatch(r->Boolean.TRUE.equals(r.get("passed")));result.put(id,done);}return result;
 }
 private List<Long> prerequisites(long module){return jdbc.queryForList("WITH RECURSIVE deps(id) AS (SELECT required_module_id FROM learning_module_prerequisites WHERE module_id=? UNION SELECT p.required_module_id FROM learning_module_prerequisites p JOIN deps d ON p.module_id=d.id) SELECT id FROM deps LIMIT 201",Long.class,module);}
 public void checkPrerequisites(long uid,Long module){if(module==null)return;var ids=prerequisites(module);if(ids.size()>200||completeModules(uid,new HashSet<>(ids)).values().stream().anyMatch(v->!v))throw new ResponseStatusException(HttpStatus.CONFLICT,"Conclua os pré-requisitos definidos pelo professor antes desta avaliação.");}
 public Map<String,Object> policy(String email,long module){access.ownModule(access.teacher(email),module);var data=jdbc.queryForMap("SELECT adaptive_skip_mastered,adaptive_revision,credential_validity_days FROM learning_modules WHERE id=?",module);data.put("prerequisites",jdbc.queryForList("SELECT required_module_id FROM learning_module_prerequisites WHERE module_id=? ORDER BY required_module_id",Long.class,module));return data;}
 @Transactional("capacitaTransactionManager")public void policy(String email,long module,ModulePolicy input){var user=access.teacher(email);access.ownModule(user,module);long course=access.courseForModule(module);jdbc.queryForObject("SELECT id FROM learning_courses WHERE id=? FOR UPDATE",Long.class,course);if(input==null||input.prerequisites()==null||input.prerequisites().size()>10||new HashSet<>(input.prerequisites()).size()!=input.prerequisites().size()||input.prerequisites().stream().anyMatch(id->id==null||id<1||id==module)||input.validityDays()!=null&&(input.validityDays()<1||input.validityDays()>3650))bad("Escolha até dez pré-requisitos diferentes e validade entre 1 e 3650 dias, quando aplicável.");for(long id:input.prerequisites())if(access.courseForModule(id)!=course)bad("Os pré-requisitos devem pertencer ao mesmo curso.");if(jdbc.update("UPDATE learning_modules SET adaptive_skip_mastered=?,credential_validity_days=?,adaptive_revision=adaptive_revision+1 WHERE id=? AND adaptive_revision=?",input.skipMastered(),input.validityDays(),module,input.revision())==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"As regras do módulo mudaram.");jdbc.update("DELETE FROM learning_module_prerequisites WHERE module_id=?",module);for(long id:input.prerequisites())jdbc.update("INSERT INTO learning_module_prerequisites(module_id,required_module_id) VALUES (?,?)",module,id);if(prerequisites(module).contains(module)||prerequisites(module).size()>200)bad("Pré-requisitos circulares ou cadeia excessiva não são permitidos.");audit(user.id(),null,"ADAPTIVE_POLICY_UPDATED");}
 private Map<Long,List<Long>> dependencies(Set<Long> roots){var result=new HashMap<Long,List<Long>>();for(long root:roots)result.put(root,new ArrayList<>());if(roots.isEmpty())return result;var rows=jdbc.queryForList("WITH RECURSIVE deps(root,id) AS (SELECT module_id,required_module_id FROM learning_module_prerequisites WHERE module_id IN ("+placeholders(roots)+") UNION SELECT d.root,p.required_module_id FROM learning_module_prerequisites p JOIN deps d ON p.module_id=d.id) SELECT root,id FROM deps ORDER BY root,id LIMIT 16081",roots.toArray());for(var row:rows)result.get(((Number)row.get("root")).longValue()).add(((Number)row.get("id")).longValue());return result;}
 @Transactional("capacitaTransactionManager")public Map<String,Object> plan(String email,UUID id,boolean refresh){long uid=access.account(email).id();jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(rs,n)->0,"adaptive:"+uid+":"+id);var goal=own(uid,id);var needs=targets(goal.get("requirements"));String sourceStatus="CURRENT";
  if(!goal.get("source").equals("MANUAL")&&(refresh||goal.get("source_checked_at")==null||((java.sql.Timestamp)goal.get("source_checked_at")).toInstant().isBefore(Instant.now().minusSeconds(300)))){try{var market=market(goal.get("source").toString(),((Number)goal.get("source_id")).longValue());needs=(List<Target>)market.get("skills");jdbc.update("UPDATE learning_adaptive_goals SET requirements=?::jsonb,source_title=?,source_checked_at=CURRENT_TIMESTAMP WHERE id=? AND student_id=?",bridge.encode(needs),market.get("title"),id,uid);goal.put("source_title",market.get("title"));}catch(ResponseStatusException unavailable){return Map.of("id",id,"title",goal.get("title"),"sourceStatus","UNAVAILABLE","notice","A vaga/previsão não está disponível ou a integração falhou. Atualize depois; não foram presumidos novos requisitos.","recommendations",List.of(),"targets",List.of());}}
  var levels=verified(uid);var rows=units(needs);boolean partial=rows.size()>80;rows=rows.stream().limit(80).toList();var signature=jdbc.queryForMap("SELECT (SELECT max(updated_at) FROM learning_lesson_progress WHERE student_id=?) AS progress,(SELECT max(started_at) FROM learning_assessment_attempts WHERE student_id=?) AS started,(SELECT max(submitted_at) FROM learning_assessment_attempts WHERE student_id=?) AS submitted",uid,uid,uid);
  var moduleIds=new HashSet<Long>();rows.forEach(r->moduleIds.add(((Number)r.get("module_id")).longValue()));var dependencies=dependencies(moduleIds);
  List<Map<String,Object>> priorAwards=List.of();if(!rows.isEmpty()){var awardArgs=new ArrayList<Object>();awardArgs.add(uid);rows.forEach(r->awardArgs.add(r.get("id")));priorAwards=jdbc.queryForList("SELECT assessment_id,competency_key FROM learning_competency_awards WHERE student_id=? AND assessment_id IN ("+String.join(",",Collections.nCopies(rows.size(),"?"))+")",awardArgs.toArray());}
  String fingerprint=RadarBridge.hash(bridge.encode(List.of(AdaptiveRules.VERSION,goal.get("revision"),needs,levels,signature,dependencies,priorAwards,rows.stream().map(r->List.of(r.get("id"),r.get("current_version_id"),r.get("adaptive_revision"))).toList(),Instant.now().getEpochSecond()/60)));
  if(!refresh&&fingerprint.equals(goal.get("cached_fingerprint"))&&goal.get("cached_result")!=null){var cached=bridge.convert(bridge.read(goal.get("cached_result")),Map.class);cached.put("cached",true);return cached;}
  if(dependencies.values().stream().anyMatch(v->v.size()>200))throw new ResponseStatusException(HttpStatus.CONFLICT,"Cadeia de pré-requisitos precisa de revisão pedagógica.");var allModules=new HashSet<>(moduleIds);dependencies.values().forEach(allModules::addAll);var moduleCompletion=completeModules(uid,allModules);var lessons=lessonData(uid,allModules);var accommodations=jdbc.queryForList("SELECT assessment_id,extended_due_at FROM learning_assessment_accommodations WHERE student_id=?",uid);List<Map<String,Object>> videos=List.of();List<Map<String,Object>> attempts=List.of();
  if(!moduleIds.isEmpty()){var args=new ArrayList<Object>();args.add(uid);args.addAll(moduleIds);videos=jdbc.queryForList("SELECT * FROM (SELECT l.id,l.title,l.module_id,l.duration_seconds,p.completed_at,row_number() OVER(PARTITION BY l.module_id ORDER BY (p.completed_at IS NOT NULL),l.sort_order,l.id) AS position FROM learning_lessons l LEFT JOIN learning_lesson_progress p ON p.lesson_id=l.id AND p.student_id=? WHERE l.module_id IN ("+placeholders(moduleIds)+") AND l.status='PUBLISHED' AND l.validation_status='READY' AND l.duration_seconds BETWEEN 180 AND 300) x WHERE position<=3",args.toArray());attempts=jdbc.queryForList("SELECT t.assessment_id,t.status,t.passed,t.score_percent,t.started_at,t.submitted_at FROM learning_assessment_attempts t JOIN learning_assessments a ON a.id=t.assessment_id WHERE t.student_id=? AND a.module_id IN ("+placeholders(moduleIds)+") ORDER BY t.started_at DESC LIMIT 2001",args.toArray());}
  List<Map<String,Object>> recommendations=new ArrayList<>();for(var row:rows){long mid=((Number)row.get("module_id")).longValue(),aid=((Number)row.get("id")).longValue();var definition=bridge.read(row.get("definition"));boolean mastered=!definition.path("competencies").isEmpty();for(var skill:definition.path("competencies")){if(skill.path("skillCode").isNull()||skill.path("skillCode").asText().isEmpty()||levels.getOrDefault(skill.path("skillCode").asText(),0)<skill.path("level").asInt(1))mastered=false;}var ownAttempts=attempts.stream().filter(a->((Number)a.get("assessment_id")).longValue()==aid).toList();boolean passed=ownAttempts.stream().anyMatch(a->Boolean.TRUE.equals(a.get("passed")));boolean failed=!ownAttempts.isEmpty()&&Boolean.FALSE.equals(ownAttempts.get(0).get("passed"));boolean canAttempt=ownAttempts.stream().anyMatch(a->a.get("status").equals("IN_PROGRESS"))||ownAttempts.size()<definition.path("maxAttempts").asInt(1);String deadline=definition.path("dueAt").asText("");if(!deadline.isEmpty()&&!deadline.equals("null")){Instant due=Instant.parse(deadline);for(var accommodation:accommodations)if(((Number)accommodation.get("assessment_id")).longValue()==aid){Instant extended=((java.sql.Timestamp)accommodation.get("extended_due_at")).toInstant();if(extended.isAfter(due))due=extended;}if(due.isBefore(Instant.now()))canAttempt=false;}
   var ls=lessons.get(mid);long total=ls==null?0:((Number)ls.get(0).get("total")).longValue(),done=ls==null?0:((Number)ls.get(0).get("completed")).longValue();boolean previous=dependencies.get(mid).size()<=200&&dependencies.get(mid).stream().allMatch(m->Boolean.TRUE.equals(moduleCompletion.get(m)));String action=AdaptiveRules.action(mastered,Boolean.TRUE.equals(row.get("adaptive_skip_mastered")),previous,total==done,failed,passed&&mastered,canAttempt);boolean needsNewEvidence=false;for(var competency:definition.path("competencies")){String code=competency.path("skillCode").asText("");if(!code.isEmpty()&&levels.getOrDefault(code,0)<competency.path("level").asInt(1))for(var award:priorAwards)if(((Number)award.get("assessment_id")).longValue()==aid&&award.get("competency_key").toString().equals(competency.path("id").asText()))needsNewEvidence=true;}if(needsNewEvidence)action="TEACHER_SUPPORT";
   final String videoAction=action;var recommendation=new LinkedHashMap<String,Object>();for(String field:List.of("course_id","module_id","course_title","module_title"))recommendation.put(field,row.get(field));recommendation.put("assessmentId",aid);recommendation.put("assessmentTitle",row.get("title"));recommendation.put("action",action);recommendation.put("explanation",needsNewEvidence?"Uma conquista anterior deste critério não comprova o nível atual. Solicite nova comprovação ao responsável; repetir esta mesma prova não restaura uma credencial expirada ou revogada.":AdaptiveRules.explanation(action));recommendation.put("prerequisites",dependencies.get(mid));recommendation.put("lessonsTotal",total);recommendation.put("lessonsCompleted",done);recommendation.put("attemptsUsed",ownAttempts.size());recommendation.put("maxAttempts",definition.path("maxAttempts").asInt());recommendation.put("passed",passed);recommendation.put("videos",action.equals("MASTERED")||action.equals("COMPLETED")?List.of():videos.stream().filter(v->((Number)v.get("module_id")).longValue()==mid&&(videoAction.equals("REVIEW")||v.get("completed_at")==null)).toList());recommendations.add(recommendation);
  }
  var targetRows=needs.stream().map(t->Map.of("skillCode",t.skillCode(),"requiredLevel",t.level(),"verifiedLevel",levels.getOrDefault(t.skillCode(),0),"met",levels.getOrDefault(t.skillCode(),0)>=t.level())).toList();long met=targetRows.stream().filter(t->Boolean.TRUE.equals(t.get("met"))).count();var result=new LinkedHashMap<String,Object>();result.put("id",id);result.put("title",goal.get("title"));result.put("source",goal.get("source"));result.put("sourceTitle",goal.get("source_title"));result.put("sourceStatus",sourceStatus);result.put("targets",targetRows);result.put("progressPercent",Math.round(100d*met/needs.size()));result.put("recommendations",recommendations);result.put("partial",partial||attempts.size()>2000);result.put("ruleVersion",AdaptiveRules.VERSION);result.put("evaluatedAt",Instant.now().toString());result.put("cached",false);result.put("notice","Regras explicáveis, sem garantia de contratação. Somente comprovações válidas reduzem lacunas; não equivale a concluir um curso. Requisitos de fonte externa são revistos a cada cinco minutos ou ao atualizar. Conteúdos de mercado sem oferta educacional correspondente ficam sem recomendação.");jdbc.update("UPDATE learning_adaptive_goals SET cached_fingerprint=?,cached_result=?::jsonb WHERE id=? AND student_id=?",fingerprint,bridge.encode(result),id,uid);audit(uid,id,"ADAPTIVE_RECALCULATED");return result;
 }
 private void audit(long uid,UUID id,String event){jdbc.update("INSERT INTO learning_assessment_audit(actor_id,resource_id,event) VALUES (?,?,?)",uid,id,event);}
}
